27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "title")
39	    private String title;
40	
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "address_line1")
46	    private String addressLine1;
47	
48	    @Column(name = "address_line2")
49	    private String addressLine2;
50	
51	    @Column(name = "city")
52	    @NotEmpty
53	    private String city;
54	
55	    @Column(name = "telephone")
56	    @NotEmpty
57	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
58	    private String telephone;
59	
60	    @Column(name = "email")
61	    private String email;
62	
63	    @Column(name = "postcode")
64	    private String postcode;
65	
66	    @Column(name = "registration_date")
67	    private LocalDate registrationDate;
68	
69	    @Column(name = "birth_date")
70	    private LocalDate birthDate;
71	
72	    @Column(name = "customer_code")
73	    private String customerCode;
74	
75	    @Column(name = "household_id")
76	    private String householdId;
77	
78	    @Column(name = "namesake_count")
79	    private Integer namesakeCount;
80	
81	    @Column(name = "bulk_signup_warning")
82	    private Boolean bulkSignupWarning;
83	
84	    @Column(name = "household_size")
85	    private Integer householdSize;
86	
87	    @Column(name = "possible_duplicate")
88	    private Boolean possibleDuplicate;
89	
90	    @Column(name = "possible_duplicate_of")
91	    private Integer possibleDuplicateOf;
92	
93	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
94	    private Set<Pet> pets;
95	
96	    public String getTitle() {
97	        return this.title;
98	    }
99	
100	    public void setTitle(String title) {
101	        this.title = title;
102	    }
103	
104	    /**
105	     * The owner's salutation: the {@link #title} followed by a single space and the last name
106	     * (e.g. {@code "DR Franklin"}), or just the last name when no title has been supplied.
107	     *
108	     * @return the formatted salutation
109	     */
110	    public String getSalutation() {
111	        if (this.title == null || this.title.isBlank()) {
112	            return this.getLastName();
113	        }
114	        return this.title + " " + this.getLastName();
115	    }
116	
117	    public String getAddress() {
118	        return this.address;
119	    }
120	
121	    public void setAddress(String address) {
122	        this.address = address;
123	    }
124	
125	    public String getAddressLine1() {
126	        return this.addressLine1;
127	    }
128	
129	    public void setAddressLine1(String addressLine1) {
130	        this.addressLine1 = addressLine1;
131	    }
132	
133	    public String getAddressLine2() {
134	        return this.addressLine2;
135	    }
136	
137	    public void setAddressLine2(String addressLine2) {
138	        this.addressLine2 = addressLine2;
139	    }
140	
141	    public String getCity() {
142	        return this.city;
143	    }
144	
145	    public void setCity(String city) {
146	        this.city = city;
147	    }
148	
149	    public String getTelephone() {
150	        return this.telephone;
151	    }
152	
153	    public void setTelephone(String telephone) {
154	        this.telephone = telephone;
155	    }
156	
157	    /**
158	     * The stored E.164 {@link #telephone} formatted for humans as the country code, a single
159	     * space, then the national digits (the digits after the country code) grouped in threes from
160	     * the left, e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}. The country code is
161	     * a single digit for the {@code +1} and {@code +7} zones and two digits otherwise.
162	     *
163	     * @return the human-formatted telephone, or the raw {@link #telephone} unchanged when it is
164	     *         {@code null} or not a {@code +} followed by digits
165	     */
166	    public String getTelephoneDisplay() {
167	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
168	            return this.telephone;
169	        }
170	        String digits = this.telephone.substring(1);
171	        int countryCodeLength = ONE_DIGIT_CALLING_CODES.contains(digits.substring(0, 1)) ? 1 : 2;
172	        if (digits.length() <= countryCodeLength) {
173	            return this.telephone;
174	        }
175	        String countryCode = digits.substring(0, countryCodeLength);
176	        String national = digits.substring(countryCodeLength);
177	        StringBuilder grouped = new StringBuilder();
178	        for (int i = 0; i < national.length(); i++) {
179	            if (i > 0 && i % 3 == 0) {
180	                grouped.append(' ');
181	            }
182	            grouped.append(national.charAt(i));
183	        }
184	        return "+" + countryCode + " " + grouped;
185	    }
186	
187	    /**
188	     * The E.164 calling codes that are a single digit ({@code +1} for the North American Numbering
189	     * Plan and {@code +7} for the Russia/Kazakhstan zone); every other calling code is two digits.
190	     */
191	    private static final Set<String> ONE_DIGIT_CALLING_CODES = Set.of("1", "7");
192	
193	    public String getEmail() {
194	        return this.email;
195	    }
196	
197	    public void setEmail(String email) {
198	        this.email = email;
199	    }
200	
201	    public String getPostcode() {
202	        return this.postcode;
203	    }
204	
205	    public void setPostcode(String postcode) {
206	        this.postcode = postcode;
207	    }
208	
209	    public LocalDate getRegistrationDate() {
210	        return this.registrationDate;
211	    }
212	
213	    public void setRegistrationDate(LocalDate registrationDate) {
214	        this.registrationDate = registrationDate;
215	    }
216	
217	    public LocalDate getBirthDate() {
218	        return this.birthDate;
219	    }
220	
221	    public void setBirthDate(LocalDate birthDate) {
222	        this.birthDate = birthDate;
223	    }
224	
225	    /**
226	     * The owner's age band, derived from the {@link #birthDate} measured in completed years
227	     * against the {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
228	     * from 18 to 64, and {@code "SENIOR"} at 65 and over.
229	     *
230	     * @return the age band, or {@code null} when either the birth date or the registration
231	     *         date has not been assigned
232	     */
233	    public String getAgeBand() {
234	        if (this.birthDate == null || this.registrationDate == null) {
235	            return null;
236	        }
237	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
238	        if (age < 18) {
239	            return "MINOR";
240	        }
241	        if (age < 65) {
242	            return "ADULT";
243	        }
244	        return "SENIOR";
245	    }
246	
247	    public String getCustomerCode() {
248	        return this.customerCode;
249	    }
250	
251	    public void setCustomerCode(String customerCode) {
252	        this.customerCode = customerCode;
253	    }
254	
255	    public String getHouseholdId() {
256	        return this.householdId;
257	    }
258	
259	    public void setHouseholdId(String householdId) {
260	        this.householdId = householdId;
261	    }
262	
263	    public Integer getNamesakeCount() {
264	        return this.namesakeCount;
265	    }
266	
267	    public void setNamesakeCount(Integer namesakeCount) {
268	        this.namesakeCount = namesakeCount;
269	    }
270	
271	    /**
272	     * Whether more than 80 owners had already been created today at the time this owner
273	     * was created, indicating an unusually high signup volume.
274	     *
275	     * @return {@code true} when the bulk-signup threshold was exceeded, otherwise
276	     *         {@code false} (never {@code null})
277	     */
278	    public Boolean getBulkSignupWarning() {
279	        return this.bulkSignupWarning != null && this.bulkSignupWarning;
280	    }
281	
282	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
283	        this.bulkSignupWarning = bulkSignupWarning;
284	    }
285	
286	    /**
287	     * The number of owners in this owner's household (owners sharing the same
288	     * {@code householdId}) as of when this owner was created, used to derive the GOLD
289	     * membership tier.
290	     *
291	     * @return the household member count, or {@code null} if it has not been assigned
292	     */
293	    public Integer getHouseholdSize() {
294	        return this.householdSize;
295	    }
296	
297	    public void setHouseholdSize(Integer householdSize) {
298	        this.householdSize = householdSize;
299	    }
300	
301	    /**
302	     * Whether this owner, though not a hard duplicate, shares an existing owner's last name and
303	     * postcode while carrying a different telephone, flagging a likely duplicate registration.
304	     *
305	     * @return {@code true} when a soft-duplicate match was found on creation, otherwise
306	     *         {@code false} (never {@code null})
307	     */
308	    public Boolean getPossibleDuplicate() {
309	        return this.possibleDuplicate != null && this.possibleDuplicate;
310	    }
311	
312	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
313	        this.possibleDuplicate = possibleDuplicate;
314	    }
315	
316	    /**
317	     * The id of the existing owner this owner may duplicate (same last name and postcode,
318	     * different telephone), or {@code null} when this owner is not a possible duplicate.
319	     *
320	     * @return the matching owner id, or {@code null}
321	     */
322	    public Integer getPossibleDuplicateOf() {
323	        return this.possibleDuplicateOf;
324	    }
325	
326	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
327	        this.possibleDuplicateOf = possibleDuplicateOf;
328	    }
329	
330	    /**
331	     * The owner's name formatted as {@code "LastName, FirstName"} from the stored names.
332	     *
333	     * @return the formatted display name
334	     */
335	    public String getDisplayName() {
336	        return this.getLastName() + ", " + this.getFirstName();
337	    }
338	
339	    /**
340	     * The owner's initials: the upper-cased first letters of the first and last
341	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
342	     *
343	     * @return the formatted initials
344	     */
345	    public String getInitials() {
346	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
347	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
348	    }
349	
350	    /**
351	     * The owner's membership number formatted as {@code "<customerCode>-M<YY>"}, where
352	     * {@code YY} is the last two digits of the registration date's year (e.g.
353	     * {@code "NSW-1A2B3C4D-M26"}).
354	     *
355	     * @return the formatted membership number, or {@code null} if the customer code or
356	     *         registration date has not been assigned
357	     */
358	    public String getMembershipNumber() {
359	        if (this.customerCode == null || this.registrationDate == null) {
360	            return null;
361	        }
362	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
363	    }
364	
365	    /**
366	     * The owner's Luhn check digit: a single digit ({@code 0}-{@code 9}) computed with the
367	     * standard Luhn algorithm over the decimal digits contained in the {@code customerCode}
368	     * (non-digit characters are ignored).
369	     *
370	     * @return the Luhn check digit, or {@code null} if the customer code has not been assigned
371	     */
372	    public Integer getCheckDigit() {
373	        if (this.customerCode == null) {
374	            return null;
375	        }
376	        int sum = 0;
377	        boolean dbl = true;
378	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
379	            char c = this.customerCode.charAt(i);
380	            if (c < '0' || c > '9') {
381	                continue;
382	            }
383	            int d = c - '0';
384	            if (dbl) {
385	                d *= 2;
386	                if (d > 9) {
387	                    d -= 9;
388	                }
389	            }
390	            sum += d;
391	            dbl = !dbl;
392	        }
393	        return (10 - (sum % 10)) % 10;
394	    }
395	
396	    /**
397	     * The owner's membership points, starting at {@code 0}. The owner gains {@code 2} when
398	     * they carry an email address, {@code 1} when they have no namesakes
399	     * ({@code namesakeCount} is {@code 0}), {@code 2} for a household of {@code 3} or more
400	     * members ({@code householdSize}), and {@code 3} for tenure of more than {@code 365}
401	     * days (measured from the {@code registrationDate}). Because a newly created owner has
402	     * zero tenure, a new owner can score at most {@code 5} points.
403	     *
404	     * @return the membership points
405	     */
406	    public Integer getMembershipPoints() {
407	        int points = 0;
408	        boolean hasEmail = this.email != null && !this.email.isBlank();
409	        if (hasEmail) {
410	            points += 2;
411	        }
412	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
413	        if (noNamesakes) {
414	            points += 1;
415	        }
416	        if (this.householdSize != null && this.householdSize >= 3) {
417	            points += 2;
418	        }
419	        if (this.registrationDate != null
420	            && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
421	            points += 3;
422	        }
423	        return points;
424	    }
425	
426	    /**
427	     * The owner's numeric membership level, from {@code 1} to {@code 4}, derived from the
428	     * {@link #getMembershipPoints() membership points}: {@code 1} for {@code 0-1} points,
429	     * {@code 2} for {@code 2-3} points, {@code 3} for {@code 4-5} points, and {@code 4} for
430	     * {@code 6} or more points. Because a newly created owner has zero tenure, a new owner
431	     * scores at most {@code 5} points and so never exceeds level {@code 3}; level {@code 4}
432	     * is reserved for owners whose tenure exceeds {@code 365} days.
433	     *
434	     * @return the membership level
435	     */
436	    public Integer getMembershipLevel() {
437	        int points = getMembershipPoints();
438	        if (points >= 6) {
439	            return 4;
440	        }
441	        if (points >= 4) {
442	            return 3;
443	        }
444	        if (points >= 2) {
445	            return 2;
446	        }
447	        return 1;
448	    }
449	
450	    /**
451	     * The owner's preferred contact channel: {@code "EMAIL"} when the owner carries an
452	     * email address, otherwise {@code "PHONE"}.
453	     *
454	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
455	     */
456	    public String getContactPreference() {
457	        boolean hasEmail = this.email != null && !this.email.isBlank();
458	        return hasEmail ? "EMAIL" : "PHONE";
459	    }
460	
461	    /**
462	     * The owner's identity key: the single derived value used for duplicate detection, formed as
463	     * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}. The telephone and
464	     * email are the already-normalized stored values and a {@code null} email or household id is
465	     * rendered as the empty string. Two owners are duplicates only when their whole identity keys
466	     * are equal; because the telephone is part of the key, household members with different
467	     * telephones have different identity keys.
468	     *
469	     * @return the derived identity key
470	     */
471	    public String getIdentityKey() {
472	        String telephonePart = this.telephone == null ? "" : this.telephone;
473	        String emailPart = this.email == null ? "" : this.email;
474	        String householdPart = this.householdId == null ? "" : this.householdId;
475	        return telephonePart + "|" + emailPart + "|" + householdPart;
476	    }
477	
478	    /**
479	     * City -> canonical region, the fixed ground truth for deriving locality.
480	     */
481	    private static final Map<String, String> CITY_REGION = Map.of(
482	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
483	
484	    /**
485	     * Region -> inclusive 4-digit postcode range {@code {low, high}}, the fixed ground truth for
486	     * deriving locality from the postcode ahead of the city.
487	     */
488	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
489	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
490	
491	    /**
492	     * The owner's locality: the canonical region resolved by the postcode range first
493	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back to the
494	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
495	     * {@code Brisbane->QLD}) when the postcode is absent or in no known range, or {@code "UNKNOWN"}
496	     * when the city is not in the table either. The postcode takes precedence so cities that share a
497	     * name are disambiguated by their postcode's region.
498	     *
499	     * @return the canonical region string, or {@code "UNKNOWN"}
500	     */
501	    public String getLocality() {
502	        String byPostcode = regionForPostcode(this.postcode);
503	        if (byPostcode != null) {
504	            return byPostcode;
505	        }
506	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
507	    }
508	
509	    /**
510	     * Region -> IANA timezone name, the fixed ground truth for deriving the owner's timezone from
511	     * its locality.
512	     */
513	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
514	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
515	
516	    /**
517	     * The owner's timezone: the IANA name resolved from the {@link #getLocality() locality} via the
518	     * fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
519	     * {@code QLD->Australia/Brisbane}), or {@code null} when the locality is not one of these regions
520	     * (e.g. {@code "UNKNOWN"}).
521	     *
522	     * @return the IANA timezone name, or {@code null}
523	     */
524	    public String getTimezone() {
525	        return REGION_TIMEZONE.get(getLocality());
526	    }
527	
528	    /**
529	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
530	     * absent, not a 4-digit number, or in no known range.
531	     *
532	     * @param postcode the owner's postcode (may be {@code null})
533	     * @return the matching region, or {@code null}
534	     */
535	    private static String regionForPostcode(String postcode) {
536	        if (postcode == null || !postcode.matches("\\d{4}")) {
537	            return null;
538	        }
539	        int value = Integer.parseInt(postcode);
540	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
541	            int[] range = entry.getValue();
542	            if (value >= range[0] && value <= range[1]) {
543	                return entry.getKey();
544	            }
545	        }
546	        return null;
547	    }
548	
549	    protected Set<Pet> getPetsInternal() {
550	        if (this.pets == null) {
551	            this.pets = new HashSet<>();
552	        }
553	        return this.pets;
554	    }
555	
556	    protected void setPetsInternal(Set<Pet> pets) {
557	        this.pets = pets;
558	    }
559	
560	    public List<Pet> getPets() {
561	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
562	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
563	        return Collections.unmodifiableList(sortedPets);
564	    }
565	
566	    public void setPets(List<Pet> pets) {
567	        this.pets = new HashSet<>(pets);
568	    }
569	
570	    public void addPet(Pet pet) {
571	        getPetsInternal().add(pet);
572	        pet.setOwner(this);
573	    }
574	
575	    /**
576	     * Return the Pet with the given name, or null if none found for this Owner.
577	     *
578	     * @param name to test
579	     * @return true if pet name is already in use
580	     */
581	    public Pet getPet(String name) {
582	        return getPet(name, false);
583	    }
584	
585	    /**
586	     * Return the Pet with the given name, or null if none found for this Owner.
587	     *
588	     * @param name to test
589	     * @return true if pet name is already in use
590	     */
591	    public Pet getPet(String name, boolean ignoreNew) {
592	        name = name.toLowerCase();
593	        for (Pet pet : getPetsInternal()) {
594	            if (!ignoreNew || !pet.isNew()) {
595	                String compName = pet.getName();
596	                compName = compName.toLowerCase();
597	                if (compName.equals(name)) {
598	                    return pet;
599	                }
600	            }
601	        }
602	        return null;
603	    }
604	
605	    public Pet getPet(Integer petId) {
606	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
607	    }
608	
609	    @Override
610	    public String toString() {
611	        return new ToStringCreator(this)
612	
613	            .append("id", this.getId())
614	            .append("new", this.isNew())
615	            .append("lastName", this.getLastName())
616	            .append("firstName", this.getFirstName())
617	            .append("address", this.address)
618	            .append("city", this.city)
619	            .append("telephone", this.telephone)
620	            .append("email", this.email)
621	            .toString();
622	    }
623	}
