163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
166	        HttpHeaders headers = new HttpHeaders();
167	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
168	        LocalDate suppliedDate = owner.getRegistrationDate();
169	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
170	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
171	        }
172	        LocalDate effectiveDate = suppliedDate != null ? suppliedDate : LocalDate.now();
173	        LocalDate registrationDate = toBusinessDay(effectiveDate);
174	        owner.setRegistrationDate(registrationDate);
175	        long createdToday = this.clinicService.findAllOwners().stream()
176	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
177	            .count();
178	        if (createdToday >= 100) {
179	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
180	        }
181	        owner.setBulkSignupWarning(createdToday > 80);
182	        if (!applyAddress(owner)) {
183	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
184	        }
185	        String telephone = toE164(owner.getTelephone());
186	        if (telephone == null) {
187	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
188	        }
189	        owner.setTelephone(telephone);
190	        if (owner.getEmail() != null) {
191	            String email = normalizeEmail(owner.getEmail());
192	            if (!EMAIL_PATTERN.matcher(email).matches()) {
193	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
194	            }
195	            if (isDisposableEmailDomain(email)) {
196	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
197	            }
198	            owner.setEmail(email);
199	        }
200	        if (!isPostcodeValidForCity(owner.getPostcode(), regionForCity(owner.getCity()))) {
201	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
202	        }
203	        String cityKey = householdKey(owner.getCity());
204	        long cityCount = this.clinicService.findAllOwners().stream()
205	            .filter(existing -> existing.getCity() != null
206	                && cityKey.equals(householdKey(existing.getCity())))
207	            .count();
208	        if (cityCount >= 50) {
209	            return new ResponseEntity<>(HttpStatus.CONFLICT);
210	        }
211	        // The household is keyed on (normalized last name, postcode): every owner derives the same
212	        // deterministic householdId from those two fields, so owners sharing them are the same
213	        // household. This computed id is what duplicate detection and the household size below key off.
214	        String householdId = householdId(owner);
215	        owner.setHouseholdId(householdId);
216	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
217	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
218	            .toList();
219	        owner.setHouseholdSize(householdMembers.size() + 1);
220	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
221	        // Household-duplicate block: a second owner in an existing household (same computed
222	        // householdId) is rejected as a duplicate. 'sharesHousehold' now only BYPASSES this block —
223	        // declaring the new owner a member — rather than creating the household link itself.
224	        if (!householdMembers.isEmpty() && !sharesHousehold) {
225	            return new ResponseEntity<>(HttpStatus.CONFLICT);
226	        }
227	        // Single consolidated duplicate check: the telephone, email and household duplicate rules are
228	        // all expressed through the one derived identityKey (telephone|email|householdId). A create is
229	        // rejected only when a new owner's WHOLE identityKey equals an existing owner's; because the
230	        // telephone is part of the key, two household members with different telephones are allowed.
231	        // This still catches a full identity repeat even when it declares sharesHousehold.
232	        String identityKey = owner.getIdentityKey();
233	        boolean identityInUse = this.clinicService.findAllOwners().stream()
234	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
235	        if (identityInUse) {
236	            return new ResponseEntity<>(HttpStatus.CONFLICT);
237	        }
238	        // Soft-duplicate detection. A declared household member (sharesHousehold) is never a suspected
239	        // duplicate. Any other owner sharing an existing owner's last name and postcode with a
240	        // different telephone is now, by definition, a household duplicate already rejected above, so
241	        // it never reaches this point; the check is retained for owners that are not household matches.
242	        if (sharesHousehold) {
243	            owner.setPossibleDuplicate(false);
244	        } else {
245	            String softDuplicateLastNameKey = householdKey(owner.getLastName());
246	            String softDuplicatePostcode = owner.getPostcode();
247	            String softDuplicateTelephone = owner.getTelephone();
248	            Owner possibleDuplicate = softDuplicatePostcode == null ? null
249	                : this.clinicService.findAllOwners().stream()
250	                    .filter(existing -> softDuplicateLastNameKey.equals(householdKey(existing.getLastName())))
251	                    .filter(existing -> softDuplicatePostcode.equals(existing.getPostcode()))
252	                    .filter(existing -> !softDuplicateTelephone.equals(existing.getTelephone()))
253	                    .min(Comparator.comparing(Owner::getId))
254	                    .orElse(null);
255	            if (possibleDuplicate != null) {
256	                owner.setPossibleDuplicate(true);
257	                owner.setPossibleDuplicateOf(possibleDuplicate.getId());
258	            } else {
259	                owner.setPossibleDuplicate(false);
260	            }
261	        }
262	        owner.setCustomerCode(customerCode(owner));
263	        String firstNameKey = householdKey(owner.getFirstName());
264	        String namesakeLastNameKey = householdKey(owner.getLastName());
265	        long namesakeCount = this.clinicService.findAllOwners().stream()
266	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
267	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
268	            .count();
269	        owner.setNamesakeCount((int) namesakeCount);
270	        this.clinicService.saveOwner(owner);
271	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
272	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
273	            owner.getMembershipLevel(), owner.getMembershipNumber());
274	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
275	        headers.setLocation(UriComponentsBuilder.newInstance()
276	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
277	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
278	    }
