280	    /**
281	     * Validates an owner's postcode against the region derived from its city. The postcode is
282	     * optional: a {@code null} value is always accepted. When present it must fall within the
283	     * inclusive range mapped to the region by {@link #REGION_POSTCODES}; a region with no known
284	     * range (e.g. the {@code "UNKNOWN"} locality of an unmapped city) accepts any 4-digit postcode.
285	     * The 4-digit syntax itself is enforced upstream by bean validation.
286	     *
287	     * @param postcode the owner's postcode (may be {@code null})
288	     * @param locality the region derived from the owner's city
289	     * @return {@code true} when the postcode is absent, the region has no range, or the postcode is
290	     *         within the region's range; {@code false} when it is out of range
291	     */
292	    /**
293	     * The canonical region for the given city via the fixed {@link #CITY_REGION} table, or
294	     * {@code "UNKNOWN"} when the city is {@code null} or not in the table.
295	     *
296	     * @param city the owner's city (may be {@code null})
297	     * @return the canonical region, or {@code "UNKNOWN"}
298	     */
299	    private String regionForCity(String city) {
300	        if (city == null) {
301	            return "UNKNOWN";
302	        }
303	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
304	    }
305	
306	    private boolean isPostcodeValidForCity(String postcode, String locality) {
307	        if (postcode == null) {
308	            return true;
309	        }
310	        int[] range = REGION_POSTCODES.get(locality);
311	        if (range == null) {
312	            return true;
313	        }
314	        int value = Integer.parseInt(postcode);
315	        return value >= range[0] && value <= range[1];
316	    }
