318	    /**
319	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
320	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
321	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
322	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
323	     * recognised country codes the national number (the digits after the country code) must also be
324	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
325	     * needs 10); a wrong national-number length yields {@code null}.
326	     *
327	     * @param telephone the raw telephone value (may be {@code null})
328	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
329	     *         a valid E.164 number
330	     */
331	    private String toE164(String telephone) {
332	        if (telephone == null) {
333	            return null;
334	        }
335	        String trimmed = telephone.trim();
336	        boolean hasCountryCode = trimmed.startsWith("+");
337	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
338	        if (hasCountryCode) {
339	            cleaned = cleaned.substring(1);
340	        }
341	        if (!cleaned.matches("[0-9]+")) {
342	            return null;
343	        }
344	        String digits;
345	        if (hasCountryCode) {
346	            digits = cleaned;
347	        } else {
348	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
349	            digits = "61" + national;
350	        }
351	        if (digits.length() < 8 || digits.length() > 15) {
352	            return null;
353	        }
354	        if (!hasValidNationalNumberLength(digits)) {
355	            return null;
356	        }
357	        return "+" + digits;
358	    }
359	
360	    /**
361	     * Checks the national-number length of an E.164 digit string (country code plus national
362	     * number, without the leading {@code '+'}) against its country code. When the number's country
363	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
364	     * country code must number exactly what that country requires; the longest matching country
365	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
366	     * only by the generic total-length rule).
367	     *
368	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
369	     * @return {@code true} if the national-number length is acceptable for the country code
370	     */
371	    private boolean hasValidNationalNumberLength(String digits) {
372	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
373	            .filter(entry -> digits.startsWith(entry.getKey()))
374	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
375	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
376	            .orElse(true);
377	    }
