379	    /**
380	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
381	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
382	     *
383	     * @param email the raw email value (must not be {@code null})
384	     * @return the trimmed, lower-cased email
385	     */
386	    private String normalizeEmail(String email) {
387	        return email.trim().toLowerCase(Locale.ROOT);
388	    }
