390	    /**
391	     * Whether the domain of the given normalized email is on the disposable-domain blocklist
392	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The domain is the substring after the last {@code '@'};
393	     * an email without an {@code '@'} carries no blocked domain.
394	     *
395	     * @param email the trimmed, lower-cased email
396	     * @return {@code true} when the email's domain is blocklisted
397	     */
398	    private boolean isDisposableEmailDomain(String email) {
399	        int at = email.lastIndexOf('@');
400	        if (at < 0) {
401	            return false;
402	        }
403	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
404	    }
