406	    /**
407	     * Applies the owner's address, preferring the structured form over the flat one. When a
408	     * non-blank {@code addressLine1} is supplied the structured fields are normalized in place and
409	     * the flat {@code address} is composed as the normalized {@code addressLine1} followed, when a
410	     * non-blank {@code addressLine2} is present, by a single space and the normalized
411	     * {@code addressLine2}. Otherwise the flat {@code address} is normalized in place. An owner
412	     * that supplies neither a non-blank {@code addressLine1} nor a non-blank flat {@code address}
413	     * is invalid.
414	     *
415	     * @param owner the owner whose address fields are normalized and composed in place
416	     * @return {@code true} when a usable address was applied, {@code false} when none was supplied
417	     */
418	    private boolean applyAddress(Owner owner) {
419	        String line1 = owner.getAddressLine1();
420	        if (line1 != null && !line1.isBlank()) {
421	            String normalizedLine1 = normalizeAddress(line1);
422	            owner.setAddressLine1(normalizedLine1);
423	            String composed = normalizedLine1;
424	            String line2 = owner.getAddressLine2();
425	            if (line2 != null && !line2.isBlank()) {
426	                String normalizedLine2 = normalizeAddress(line2);
427	                owner.setAddressLine2(normalizedLine2);
428	                composed = normalizedLine1 + " " + normalizedLine2;
429	            }
430	            owner.setAddress(composed);
431	            return true;
432	        }
433	        String address = normalizeAddress(owner.getAddress());
434	        if (address == null || address.isEmpty()) {
435	            return false;
436	        }
437	        owner.setAddress(address);
438	        return true;
439	    }
