441	    /**
442	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
443	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
444	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
445	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
446	     * normalized form, and every household comparison uses it.
447	     *
448	     * @param address the raw address value (may be {@code null})
449	     * @return the normalized address, or {@code null} if the input was {@code null}
450	     */
451	    private String normalizeAddress(String address) {
452	        if (address == null) {
453	            return null;
454	        }
455	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
456	        if (collapsed.isEmpty()) {
457	            return collapsed;
458	        }
459	        String[] tokens = collapsed.split(" ");
460	        StringBuilder sb = new StringBuilder(collapsed.length());
461	        for (int i = 0; i < tokens.length; i++) {
462	            if (i > 0) {
463	                sb.append(' ');
464	            }
465	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
466	        }
467	        return sb.toString();
468	    }
469	
470	    /**
471	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
472	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
473	     * so that owners are compared case-insensitively with collapsed whitespace.
474	     *
475	     * @param value the raw value (must not be {@code null})
476	     * @return the normalized comparison key
477	     */
478	    private String householdKey(String value) {
479	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
480	    }
481	
482	    /**
483	     * Derives a stable, shared household identifier for the owner's household: the first 12 hex
484	     * characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}, where the
485	     * last name is normalized with {@link #householdKey} and an absent postcode is rendered as the
486	     * empty string. Because it is a pure function of the last name and postcode, every owner sharing
487	     * those two fields derives the identical identifier and therefore belongs to the same household.
488	     *
489	     * @param owner the owner whose household identifier is derived
490	     * @return the stable household identifier
491	     */
492	    private String householdId(Owner owner) {
493	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
494	        String key = householdKey(owner.getLastName()) + "|" + postcode;
495	        try {
496	            byte[] digest = MessageDigest.getInstance("SHA-256")
497	                .digest(key.getBytes(StandardCharsets.UTF_8));
498	            StringBuilder sb = new StringBuilder(digest.length * 2);
499	            for (byte b : digest) {
500	                sb.append(String.format("%02x", b));
501	            }
502	            return sb.substring(0, 12);
503	        }
504	        catch (java.security.NoSuchAlgorithmException e) {
505	            throw new IllegalStateException("SHA-256 not available", e);
506	        }
507	    }
508	
509	    /**
510	     * Builds the customer code for a newly registered owner in the form
511	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the region code derived from the owner's
512	     * postcode (the same region derivation shared with {@link Owner#getLocality() locality}:
513	     * postcode range first, falling back to the city, or {@code 'UNKNOWN'}) and {@code HASH8} is the
514	     * first 8 upper-case hex characters of the SHA-256 digest of the normalized telephone
515	     * concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). When the computed code
516	     * collides with an existing owner's customer code, {@code '-<n>'} is appended using the
517	     * smallest {@code n} of 2 or more that makes the result unique, guaranteeing distinct owners
518	     * always receive distinct customer codes.
519	     *
520	     * @param owner the owner whose customer code is derived (with normalized telephone already set)
521	     * @return the assigned customer code
522	     */
523	    private String customerCode(Owner owner) {
524	        String region = owner.getLocality();
525	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName(), 8);
526	        String base = region + "-" + hash8;
527	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
528	            .map(Owner::getCustomerCode)
529	            .filter(code -> code != null)
530	            .collect(Collectors.toSet());
531	        if (!existingCodes.contains(base)) {
532	            return base;
533	        }
534	        int n = 2;
535	        while (existingCodes.contains(base + "-" + n)) {
536	            n++;
537	        }
538	        return base + "-" + n;
539	    }
540	
541	    /**
542	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
543	     * UTF-8 bytes of {@code input}.
544	     *
545	     * @param input  the value to hash
546	     * @param length the number of leading hex characters to keep
547	     * @return the truncated, upper-cased hex digest
548	     */
549	    private String sha256UpperHex(String input, int length) {
550	        try {
551	            byte[] digest = MessageDigest.getInstance("SHA-256")
552	                .digest(input.getBytes(StandardCharsets.UTF_8));
553	            StringBuilder sb = new StringBuilder(digest.length * 2);
554	            for (byte b : digest) {
555	                sb.append(String.format("%02x", b));
556	            }
557	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
558	        }
559	        catch (java.security.NoSuchAlgorithmException e) {
560	            throw new IllegalStateException("SHA-256 not available", e);
561	        }
562	    }
