564	    /**
565	     * Rolls a registration date forward onto a business day. When the given date falls on a
566	     * Saturday or Sunday it is advanced to the following Monday; a weekday is returned unchanged.
567	     *
568	     * @param date the effective registration date (must not be {@code null})
569	     * @return the same date if it is a weekday, otherwise the next Monday
570	     */
571	    private LocalDate toBusinessDay(LocalDate date) {
572	        DayOfWeek dayOfWeek = date.getDayOfWeek();
573	        if (dayOfWeek == DayOfWeek.SATURDAY) {
574	            return date.plusDays(2);
575	        }
576	        if (dayOfWeek == DayOfWeek.SUNDAY) {
577	            return date.plusDays(1);
578	        }
579	        return date;
580	    }
