583	    @Override
584	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
585	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
586	        if (currentOwner == null) {
587	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
588	        }
589	        String email = ownerFieldsDto.getEmail();
590	        if (email != null) {
591	            email = normalizeEmail(email);
592	            if (!EMAIL_PATTERN.matcher(email).matches()) {
593	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
594	            }
595	        }
596	        String telephone = toE164(ownerFieldsDto.getTelephone());
597	        if (telephone == null) {
598	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
599	        }
600	        currentOwner.setAddress(ownerFieldsDto.getAddress());
601	        currentOwner.setCity(ownerFieldsDto.getCity());
602	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
603	        currentOwner.setLastName(ownerFieldsDto.getLastName());
604	        currentOwner.setTelephone(telephone);
605	        currentOwner.setEmail(email);
606	        this.clinicService.saveOwner(currentOwner);
607	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
608	    }
609	
610	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
611	    @Transactional
612	    @Override
613	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
614	        Owner owner = this.clinicService.findOwnerById(ownerId);
615	        if (owner == null) {
616	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
617	        }
618	        this.clinicService.deleteOwner(owner);
619	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
620	    }
621	
622	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
623	    @Override
624	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
625	        Owner owner = this.clinicService.findOwnerById(ownerId);
626	        if (owner == null) {
627	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
628	        }
629	        HttpHeaders headers = new HttpHeaders();
630	        Pet pet = petMapper.toPet(petFieldsDto);
631	        owner.setId(ownerId);
632	        pet.setOwner(owner);
633	        pet.getType().setName(null);
634	        this.clinicService.savePet(pet);
635	        PetDto petDto = petMapper.toPetDto(pet);
636	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
637	            .buildAndExpand(pet.getId()).toUri());
638	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
639	    }
640	
641	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
642	    @Override
643	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
644	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
645	        if (currentOwner != null) {
646	            Pet currentPet = this.clinicService.findPetById(petId);
647	            if (currentPet != null) {
648	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
649	                currentPet.setName(petFieldsDto.getName());
650	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
651	                this.clinicService.savePet(currentPet);
652	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
653	            }
654	        }
655	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
656	    }
657	
658	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
659	    @Override
660	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
661	        HttpHeaders headers = new HttpHeaders();
662	        Visit visit = visitMapper.toVisit(visitFieldsDto);
663	        Pet pet = new Pet();
664	        pet.setId(petId);
665	        visit.setPet(pet);
666	        this.clinicService.saveVisit(visit);
667	        VisitDto visitDto = visitMapper.toVisitDto(visit);
668	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
669	            .buildAndExpand(visit.getId()).toUri());
670	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
671	    }
672	
673	
674	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
